package ais.action.master.generic.v2.test;
import ais.common.newui.sekolah.NewUiTagihanService;import ais.common.newui.sekolah.NewUiTagihanService.Filter;import ais.common.newui.sekolah.NewUiTagihanService.Snapshot;
/** Smoke test read-only terhadap database lokal; tidak meninggalkan data uji. */
public final class TagihanWorkflowDatabaseSelfTest{private TagihanWorkflowDatabaseSelfTest(){}public static void main(String[]a){NewUiTagihanService service=new NewUiTagihanService();Filter f=new Filter();f.size=10;Snapshot s=service.load(f,null);check(s.total>=0,"total");check(s.rows.size()<=10,"paging");check(s.options!=null,"options");if(!s.rows.isEmpty()){check(s.rows.get(0).id!=null,"row id");check(s.rows.get(0).nominal>=0,"nominal");check(service.history(s.rows.get(0).id,null)!=null,"history");for(NewUiTagihanService.Row r:s.rows)if(r.canMove){check(service.moveTargets(r.id,null)!=null,"move targets");break;}}System.out.println("TagihanWorkflowDatabaseSelfTest OK total="+s.total+" rows="+s.rows.size());System.exit(0);}private static void check(boolean v,String m){if(!v)throw new IllegalStateException(m);}}
